panel:
var price = 100;
var mainHuanShou;
this.open = function()
{
   this.setMainHuanShou();
   this.flashView();
   this.openPanel();
};
this.setHuanShou = function(target)
{
   if(this.mainRect.hitTest(_root._xmouse,_root._ymouse,true))
   {
      this.setMainHuanShou(target);
      return true;
   }
   return false;
};
this.setMainHuanShou = function(target)
{
   if(target.type)
   {
      this.mainHuanShou = target;
      this.mainHuanShouView._visible = true;
      this.mainHuanShouView.gotoAndStop(this.mainHuanShou.type);
      this.huanShouName.text = this.mainHuanShou.type;
      this.showInfo();
      return true;
   }
   this.huanShouName.text = "";
   this.mainHuanShou = undefined;
   this.mainHuanShouView._visible = false;
   this.showInfo();
   return false;
};
this.superEvolve = function()
{
   if(this.mainHuanShou == undefined)
   {
      return false;
   }
   if(this.mainHuanShou.allFen < 5000)
   {
      _global.sysMsg.addMsg("极品50星以上的幻兽才能评称");
      return false;
   }
   if(this.mainHuanShou.titleNum > 0)
   {
      return false;
   }
   var _loc3_;
   _loc3_ = this._parent.allTitle.length;
   while(_loc3_ > 0)
   {
      if(this._parent.allTitle[_loc3_ - 1].type == this.mainHuanShou.type)
      {
         this.mainHuanShou.titleNum = this._parent.allTitle[_loc3_ - 1].number + 2;
         if(this._parent.allTitle[_loc3_ - 1].number > 0)
         {
            this._parent.allTitle[_loc3_ - 1].number -= 1;
         }
         this.mainHuanShou.maxZs += 50;
         break;
      }
      _loc3_ = _loc3_ - 1;
   }
   this.mainHuanShou.checkUp();
   this._parent.flashHuanShouView();
   this.closePanel();
   _global.msg.open("\r\r\r幻兽" + mainHuanShou.type + "获得了" + mainHuanShou.titleName + "称号");
   _global.msg.open("\r\r\r幻兽" + mainHuanShou.type + "最大转世次数增加50次");
   return true;
};
this.flashView = function()
{
   this.setMainHuanShou(this.mainHuanShou);
};
this.showInfo = function()
{
};

